"""Half-wave rectifier: y = max(x, 0)."""

import numpy as np
from gnuradio import gr


class blk(gr.sync_block):
    """Half-wave rectifier: y = max(x, 0)."""

    def __init__(self):
        gr.sync_block.__init__(self, name="Half-Wave Rectifier", in_sig=[np.float32], out_sig=[np.float32])

    def work(self, input_items, output_items):
        x = input_items[0]
        output_items[0][:] = np.maximum(x, 0.0)
        return len(output_items[0])
